      .filter((doc) => isRecord(doc) && typeof doc.ms_document_id === 'string' && doc.ms_document_id.trim() !== '')
      .map((doc) => [doc.ms_document_id, doc])
  );
}

function buildSourceSpanIndex(sourceSpans) {
  return new Map(
    asArray(sourceSpans?.source_spans)
      .filter((span) => isRecord(span) && typeof span.source_span_id === 'string' && span.source_span_id.trim() !== '')
      .map((span, index) => [span.source_span_id, { span, index }])
  );
}
