Validators must verify that upstream source files exist and parse as valid JSON. Let's update `validateSourceArtifacts` to parse the files as JSON and record a diagnostic if they are malformed.

```javascript
function validateSourceArtifacts({ errors, harness, root }) {
  if (harness.source_artifacts !== undefined && !Array.isArray(harness.source_artifacts)) {
    pushError(errors, 'source_artifacts_invalid_type', '/source_artifacts', 'source_artifacts must be an array');
    return;
  }
  const presentRoles = new Set();
  for (const [index, artifact] of asArray(harness.source_artifacts).entries()) {
    if (!isRecord(artifact)) {
      pushError(errors, 'source_artifact_invalid_type', `/source_artifacts/${index}`, 'source artifact must be an object');
      continue;
    }
    if (typeof artifact.role === 'string') presentRoles.add(artifact.role);
    if (typeof artifact.path !== 'string' || artifact.path.length === 0) {
      pushError(errors, 'source_artifact_path_invalid', `/source_artifacts/${index}/path`, 'source artifact path is required');
      continue;
    }
    if (!fs.existsSync(resolvePath(root, artifact.path))) {
      pushError(errors, 'upstream_file_missing', artifact.path, `upstream file is missing: ${artifact.path}`);
    } else if (artifact.path.endsWith('.json')) {
      try {
        JSON.parse(fs.readFileSync(resolvePath(root, artifact.path), 'utf8'));
      } catch (error) {
        pushError(errors, 'upstream_file_malformed_json', artifact.path, `upstream file is not valid JSON: ${error.message}`);
      }
    }
  }
  for (const role of EXPECTED_SOURCE_ARTIFACT_ROLES) {
    if (!presentRoles.has(role)) {
      pushError(errors, 'missing_source_artifact_role', '/source_artifacts', `expected source artifact role is missing: ${role}`);
    }
  }
}
