When validating expected array fields, if a field is present but has an invalid type, we must record an explicit invalid-type diagnostic and continue processing in a fail-closed manner. Also, we should defensively handle potentially null or malformed entries safely.

```javascript
function validateRows({ errors, harness, root, paths }) {
  if (harness.rows !== undefined && !Array.isArray(harness.rows)) {
    pushError(errors, 'rows_invalid_type', '/rows', 'rows must be an array');
    return;
  }
  const rows = asArray(harness.rows);
  const questionIds = rows.map((row) => row?.question_id);
  const uniqueQuestionIds = new Set(questionIds.filter(Boolean));
  if (uniqueQuestionIds.size !== questionIds.length) {
    pushError(errors, 'question_row_ids_not_unique', '/rows', 'question row ids must be unique');
  }

  let expectedQuestionIds = new Set();
  try {
    expectedQuestionIds = new Set(asArray(readJson(root, paths.runtimeSourceMapIn).rows)
      .map((row) => row.question_row_id ?? row.question_key)
      .filter(Boolean));
  } catch {
    expectedQuestionIds = new Set();
  }
  for (const id of expectedQuestionIds) {
    if (!uniqueQuestionIds.has(id)) {
      pushError(errors, 'question_row_missing', '/rows', `missing question row: ${id}`);
    }
  }

  rows.forEach((row, index) => {
    if (!isRecord(row)) {
      pushError(errors, 'question_row_invalid_type', `/rows/${index}`, 'question row must be an object');
      return;
    }
    if (row.locator_candidates !== undefined && !Array.isArray(row.locator_candidates)) {
      pushError(errors, 'locator_candidates_invalid_type', `/rows/${index}/locator_candidates`, 'locator_candidates must be an array');
    }
    for (const [candidateIndex, candidate] of asArray(row.locator_candidates).entries()) {
      const pathPrefix = `/rows/${index}/locator_candidates/${candidateIndex}`;
      if (!isRecord(candidate)) {
        pushError(errors, 'locator_candidate_invalid_type', pathPrefix, 'locator candidate must be an object');
        continue;
      }
      if (!locatorCandidateHasValidPageConvention(candidate)) {
        pushError(
          errors,
          'page_numbering_convention_violation',
          pathPrefix,
          'locator candidates must use zero-based index and one-based page number',
        );
      }
      if (!locatorCandidateHasComponent(candidate)) {
        pushError(
          errors,
          'component_code_missing',
          `${pathPrefix}/ms_component_code`,
          'page locators require ms_component_code',
        );
      }
      if (
        candidate.unsupported_guess === true
        || /guess/iu.test(String(candidate.locator_source ?? ''))
      ) {
        pushError(
          errors,
          'unsupported_guess_marked_as_locator',
          pathPrefix,
          'unsupported guesses cannot be promoted to locator candidates',
        );
      }
    }

    if (
      row.locator_status_after === 'document_only'
      && (
        row.student_display_allowed === true
        || row.document_reveal_policy?.full_document_student_reveal_allowed === true
        || row.document_reveal_policy?.document_only_default_display_mode !== 'unavailable'
      )
    ) {
      pushError(
        errors,
        'document_only_student_reveal_allowed',
        `/rows/${index}/document_reveal_policy`,
        'document_only rows must remain non-student-display by default',
      );
    }

    const mustPreserveAmbiguity =
      row.locator_status_before === 'ambiguous'
      || (row.locator_status_before === 'page_located' && asArray(row.locator_candidates).length > 1);
    if (
      mustPreserveAmbiguity
      && (
        row.ambiguity_preserved !== true
        || row.selected_locator !== null
        || (row.locator_status_before === 'ambiguous' && row.locator_status_after !== 'ambiguous')
      )
    ) {
      pushError(
        errors,
        'ambiguity_collapsed_by_unsupported_guess',
        `/rows/${index}`,
        'ambiguous source evidence must not be collapsed into a selected page guess',
      );
    }

    const exposure = row.page_exposure_risk ?? {};
    if (
      exposure.page_contains_other_questions === true
      || Number(exposure.exposed_neighbor_question_count ?? 0) > 0
    ) {
      if (
        exposure.requires_user_warning !== true
        || !Array.isArray(exposure.exposed_neighbor_question_labels)
        || exposure.exposed_neighbor_question_labels.length === 0
      ) {
        pushError(
          errors,
          'same_page_exposure_warning_missing',
          `/rows/${index}/page_exposure_risk`,
          'same-page multi-question exposure requires warning metadata and neighbor labels',
        );
      }
    }
  });
}
