+    ['post_attempt_ms_question_source_inventory', paths.questionSourceInventoryIn],
+    ['ms_document_inventory', paths.msDocumentInventoryIn],
+    ['source_spans', paths.sourceSpansIn],
+    ['question_mark_scheme_links_candidates', paths.layerCLinksIn],
+    ['full_beta_runtime_source_map', paths.runtimeSourceMapIn],
+    ['question_runtime_payload_all_3530_read_model', paths.runtimeReadModelIn],
+  ].map(([role, relPath]) => sourceArtifact(root, role, relPath));
+}
+
+function loadInputs(root, paths) {
+  const diagnostics = [];
+  return {
+    diagnostics,
+    questionSourceInventory: safeReadJson(
+      root,
+      paths.questionSourceInventoryIn,
+      'post_attempt_ms_question_source_inventory',
+      diagnostics,
+    ),
+    msDocumentInventory: safeReadJson(root, paths.msDocumentInventoryIn, 'ms_document_inventory', diagnostics),
+    sourceSpans: safeReadJson(root, paths.sourceSpansIn, 'source_spans', diagnostics),
+    layerCLinks: safeReadJson(
+      root,
+      paths.layerCLinksIn,
+      'question_mark_scheme_links_candidates',
+      diagnostics,
+    ),
+    runtimeSourceMap: safeReadJson(root, paths.runtimeSourceMapIn, 'full_beta_runtime_source_map', diagnostics),
+    runtimeReadModel: safeReadJson(
+      root,
+      paths.runtimeReadModelIn,
+      'question_runtime_payload_all_3530_read_model',
+      diagnostics,
+    ),
+  };
+}
+
+function buildDocIndex(documents) {
+  return new Map(asArray(documents).filter(isRecord).map((doc) => [doc.ms_document_id, doc]));
+}
+
+function buildSourceSpanIndex(sourceSpans) {
+  return new Map(asArray(sourceSpans?.source_spans)
+    .filter(isRecord)
+    .map((span, index) => [span.source_span_id, { span, index }]));
+}
